CREATE TABLE orders (
  order_id      NUMBER GENERATED ALWAYS AS IDENTITY,
  customer_name VARCHAR2(50)  NOT NULL,
  amount        NUMBER(10,2)  NOT NULL,
  order_date    DATE DEFAULT SYSDATE NOT NULL,
  CONSTRAINT orders_pk PRIMARY KEY (order_id)
);

INSERT INTO orders (customer_name, amount) VALUES ('Priya', 1250.00);
INSERT INTO orders (customer_name, amount) VALUES ('Rahul', 899.50);
INSERT INTO orders (customer_name, amount) VALUES ('Anita', 4300.00);
COMMIT;

SELECT order_id, customer_name, amount
  FROM orders
 ORDER BY order_id;

UPDATE orders
   SET order_id = 99
 WHERE order_id = 1;

CREATE TABLE payments (
  payment_id NUMBER GENERATED BY DEFAULT AS IDENTITY,
  order_id   NUMBER        NOT NULL,
  amount     NUMBER(10,2)  NOT NULL,
  CONSTRAINT payments_pk PRIMARY KEY (payment_id)
);

INSERT INTO payments (order_id, amount) VALUES (1, 1250.00);
INSERT INTO payments (payment_id, order_id, amount) VALUES (500, 2, 899.50);
COMMIT;

SELECT payment_id, order_id, amount FROM payments ORDER BY payment_id;

CREATE TABLE refunds (
  refund_id  NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
  payment_id NUMBER       NOT NULL,
  amount     NUMBER(10,2) NOT NULL,
  CONSTRAINT refunds_pk PRIMARY KEY (refund_id)
);

INSERT INTO refunds (refund_id, payment_id, amount) VALUES (NULL, 1, 250.00);
INSERT INTO refunds (payment_id, amount) VALUES (500, 100.00);
COMMIT;

SELECT refund_id, payment_id, amount FROM refunds ORDER BY refund_id;

CREATE TABLE invoices (
  invoice_no NUMBER GENERATED ALWAYS AS IDENTITY
             (START WITH 1000 INCREMENT BY 1 CACHE 100),
  order_id   NUMBER NOT NULL,
  CONSTRAINT invoices_pk PRIMARY KEY (invoice_no)
);

INSERT INTO invoices (order_id) VALUES (1);
INSERT INTO invoices (order_id) VALUES (2);
COMMIT;

SELECT invoice_no, order_id FROM invoices ORDER BY invoice_no;

DECLARE
  v_order_id orders.order_id%TYPE;
BEGIN
  INSERT INTO orders (customer_name, amount)
  VALUES ('Meera', 2100.00)
  RETURNING order_id INTO v_order_id;

  DBMS_OUTPUT.PUT_LINE('New order id: ' || v_order_id);
  COMMIT;
END;
